namespace CSharpPracticum.Tasks.Level2;
internal class Task34_WordGroups:ITask{public string Title=>"Задание 34: LINQ — группировка слов по первой букве";public string Description=>"Сгруппировать список слов по первой букве и отсортировать.";public string[] Requirements=>new[]{"Взять 10+ слов.","Сгруппировать через GroupBy(w => w[0]).", "Сортировать группы по букве, слова — внутри группы."};public void Run(){string[] words={"арбуз","апельсин","банан","берёза","вишня","ветер","город","гора","дом","дорога","ежевика","ель"};foreach(var group in words.GroupBy(w=>w[0]).OrderBy(g=>g.Key))Console.WriteLine($"{group.Key}: {string.Join(", ",group.OrderBy(w=>w))}");}}
